  'import { Image } from "react-native";\n\nexport default function App() {\n  // Las imágenes de internet necesitan width y height\n  return <Image source={{ uri: "https://picsum.photos/200" }} style={{ width: 200, height: 200, borderRadius: 12 }} />;\n}',
