R("Context para estado global", "createContext", "forma de compartir datos entre pantallas sin pasarlos a mano", "saber en todas las pantallas quién inició sesión",
  'import { createContext, useContext, useState } from "react";\nimport { Button, Text, View } from "react-native";\n\nconst Sesion = createContext(null);\nfunction Perfil() { const { usuario } = useContext(Sesion); return <Text>Hola {usuario ?? "invitado"}</Text>; }\n\nexport default function App() {\n  const [usuario, setUsuario] = useState(null);\n  return (\n    <Sesion.Provider value={{ usuario }}>\n      <View style={{ padding: 40 }}><Perfil /><Button title="Entrar" onPress={() => setUsuario("Ana")} /></View>\n    </Sesion.Provider>\n  );\n}',
  "comparte el usuario con todas las pantallas", "usar el contexto fuera de su Provider"),
R("Zustand en React Native", "zustand", "librería pequeña para manejar estado global", "guardar el carrito de compras de toda la app",
  'import { create } from "zustand";\nimport { Button, Text, View } from "react-native";\n\nconst useCarrito = create((set) => ({ items: 0, agregar: () => set((s) => ({ items: s.items + 1 })) }));\n\nexport default function App() {\n  const { items, agregar } = useCarrito();\n  return <View style={{ padding: 40 }}><Text>Carrito: {items}</Text><Button title="Agregar" onPress={agregar} /></View>;\n}',
  "maneja el carrito de forma global", "guardar en el estado global datos que solo usa una pantalla"),
