  'import { useState } from "react";\nimport { Button, FlatList, Text, TextInput, View } from "react-native";\n\n// Lista de tareas: estado, entrada, lista y borrado\nexport default function App() {\n  const [t, setT] = useState("");\n  const [tareas, setTareas] = useState([]);\n  return (\n    <View style={{ padding: 40, gap: 8 }}>\n      <TextInput placeholder="Nueva tarea" value={t} onChangeText={setT} />\n      <Button title="Agregar" onPress={() => { if (t.trim()) { setTareas([...tareas, { id: Date.now().toString(), t }]); setT(""); } }} />\n      <FlatList data={tareas} keyExtractor={(x) => x.id} renderItem={({ item }) => <Text onPress={() => setTareas(tareas.filter((y) => y.id !== item.id))}>• {item.t}</Text>} />\n    </View>\n  );\n}',
